(window.ArduinoSketches=window.ArduinoSketches||{})["b1_03_signal_variables"]={"ok":true,"flash":1078,"ram":9,"program":"","name":"b1_03_signal_variables","source":"// ==================================================================\n//   BAND 1, PART 8  -  THE SAME THING, WITH NAMES\n//\n//   WHAT IT DOES\n//     Exactly the same as b1_02. Nothing about the behaviour changes.\n//\n//   WHAT IS DIFFERENT\n//     Every pin number and every timing now has a name at the top.\n//     Change the crossing from 5 seconds to 8 by editing ONE line.\n//\n//     Try the same change in b1_02 and count how many lines you had\n//     to edit there. Those two numbers are the lesson of this band.\n//\n//   WIRING\n//     Exactly the same as b1_02.\n// ==================================================================\n\nint redPin = 9;\nint yellowPin = 8;\nint greenPin = 7;\n\nint stopTime = 5000;\nint changeTime = 1500;\nint goTime = 5000;\n\nvoid setup() {\n  pinMode(redPin, OUTPUT);\n  pinMode(yellowPin, OUTPUT);\n  pinMode(greenPin, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(redPin, HIGH);\n  digitalWrite(yellowPin, LOW);\n  digitalWrite(greenPin, LOW);\n  delay(stopTime);\n\n  digitalWrite(redPin, HIGH);\n  digitalWrite(yellowPin, HIGH);\n  digitalWrite(greenPin, LOW);\n  delay(changeTime);\n\n  digitalWrite(redPin, LOW);\n  digitalWrite(yellowPin, LOW);\n  digitalWrite(greenPin, HIGH);\n  delay(goTime);\n\n  digitalWrite(redPin, LOW);\n  digitalWrite(yellowPin, HIGH);\n  digitalWrite(greenPin, LOW);\n  delay(changeTime);\n}\n","compiler":"arduino-cli 1.5.1, arduino:avr:uno"};
